// Runs once per clinic, so each clinic's bookings are paired with that clinic.
// Maps bookings to the shape pps.sync_appointments expects. A status the
// calendar cannot state (booked, confirmed, unknown) arrives as 'unmarked';
// the database never turns a recorded outcome back into unmarked.

const clinic = $('Active clinics').item.json;
const body = $json;
const bookings = Array.isArray(body) ? body : (body.bookings || body.data);

// An empty result and a failed call look the same until checked.
if (!Array.isArray(bookings)) {
  throw new Error('Unreadable bookings response for ' + clinic.clinic_id);
}

const OUTCOME = {
  attended: 'attended', completed: 'attended',
  noshow: 'no_show', no_show: 'no_show',
  cancelled: 'cancelled', rejected: 'cancelled',
};

const rows = bookings
  .map((b) => ({
    appointment_id: String(b.uid || b.id || ''),
    clinic_id: clinic.clinic_id,
    patient_ref: b.attendeeId || b.contact_id || null,
    booked_at: b.createdAt || b.booked_at || b.startTime || b.start,
    starts_at: b.startTime || b.start || b.starts_at,
    outcome: OUTCOME[String(b.status || b.outcome || '').toLowerCase().replace(/[^a-z_]/g, '')] || 'unmarked',
    is_new_patient: b.isNewPatient !== false,
    booked_by: b.bookedByAgent ? 'agent' : 'staff',
  }))
  .filter((r) => r.appointment_id && r.starts_at);

return { json: { clinic_id: clinic.clinic_id, count: rows.length, rows } };

